    /** Linhas entre o título e o quarto, que identificam quem é o hóspede (e a empresa, se houver). */
    List<String> partyLines(String guestName);

    /** Linhas depois do total. */
    default List<String> footerLines(Document document) {
        return List.of();
    }
}
